dir.commands:
declare @ten_dvcs nvarchar(256) select @ten_dvcs = ten_dvcs from dmdvcs where ma_dvcs = @@unit select N'this._unit = ''' + @@unit + N'''; this._unitName=''' + replace(replace(isnull(@ten_dvcs, ''), '\', '\\'), '''', '\''') + '''; active$VoucherFilter$(this);' as message return
&XMLWhenFilterClosing;
exec dbo.zrs_zGenerateHD9Load @ngay_ct1, @ngay_ct2, @ma_kh, @ma_dvcs, @@userID, @@admin

script.text:
			&OutlineEntry;

function active$VoucherFilter$(f) {
	f.setItemValues('ma_dvcs, ten_dvcs%l', [f._unit, f._unitName]);	
	f.add_onResponseComplete(on$Filter$ResponseComplete);
}
function close$VoucherFilter$(f) {try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid;
			g._ma_dvcs = f.getItemValue('ma_dvcs');
			g._alterTitle = [null, [['%d1', f.getItem('ngay_ct1').value, true], ['%d2', f.getItem('ngay_ct2').value, true], ['%d3', f.getItem('ma_dvcs').value, true]]];
			break;
		default:
			break;
	}
}
